class Solution {
  public int maxFont(String text, int w, int h, int[] fonts, FontInfo fontInfo) {
    int[] freq = new int[26];
    for (char c : text.toCharArray()) freq[c - 'a']++;
    // fitting is monotone in the font size: binary search the largest that fits
    int lo = 0, hi = fonts.length - 1, best = -1;
    while (lo <= hi) {
      int mid = (lo + hi) >>> 1, size = fonts[mid];
      long width = 0;
      for (int c = 0; c < 26; c++) if (freq[c] > 0) width += (long) freq[c] * fontInfo.getWidth(size, (char) ('a' + c));
      if (width <= w && fontInfo.getHeight(size) <= h) {
        best = size;
        lo = mid + 1;
      } else hi = mid - 1;
    }
    return best;
  }
}
